(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-631":{scenario:{company:"Trường An Cost Consultants",supervisor:{name:"Kiều Thị Phương Thảo",role:{vi:"Trưởng nhóm Dự toán",en:"Lead Quantity Surveyor"}},ref_code:"BOQ-2318",title:{vi:"Đo bóc đúng. Áp định mức đúng. Giá trị trung thực.",en:"Measure right. Apply the right norm. Report true value."},brief:{vi:"Bạn soát xét bảng khối lượng BOQ-2318 phần móng nhà xưởng. Cốt thép móng M1 dùng thanh D16; bảng thống kê cốt thép đã duyệt cho tổng chiều dài D16 là 2 980 m. Bản nháp áp sai nhóm đường kính của định mức và tính sai khối lượng thép. Hãy sửa nhóm định mức và khối lượng thép D16 (kg, làm tròn đến kg), rồi lập báo cáo có căn cứ. Đơn giá, định mức trong bài là số liệu mô phỏng.",en:"You are reviewing bill of quantities BOQ-2318 for a factory's foundations. Footing M1 uses D16 bars; the approved bar schedule gives a total D16 length of 2,980 m. The draft applies the wrong diameter group of the norm and miscalculates the steel weight. Correct the norm group and the D16 weight (kg, rounded to 1 kg), then write an evidence-based report. Rates and norms here are simulated."},reference_title:{vi:"Bảng thống kê cốt thép & bảng tính đã duyệt",en:"Approved bar schedule & quantity worksheet"},fields:[{id:"NORM_GROUP",label:{vi:"Nhóm đường kính áp định mức thép D16",en:"Norm diameter group for D16 rebar"},initial:"D>18",expected:"D10-18",choices:["D<=10","D10-18","D>18"],reference:"Bảng thống kê cốt thép móng M1",ref_value:{vi:"Thanh D16 (đường kính danh nghĩa 16 mm); định mức chia nhóm D<=10, D10-18 (trên 10 đến 18 mm), D>18 mm",en:"D16 bar (16 mm nominal); norm groups D<=10, D10-18 (over 10 up to 18 mm), D>18 mm"},hint:{vi:"Nhóm định mức xét theo đường kính danh nghĩa của thanh, không theo vị trí hay tầm quan trọng của cấu kiện.",en:"The norm group depends on the bar's nominal diameter, not on the element's location or importance."}},{id:"STEEL_KG",label:{vi:"Khối lượng thép D16 (kg)",en:"D16 steel weight (kg)"},initial:"3604",expected:"4707",reference:"Bảng tính khối lượng cốt thép",ref_value:{vi:"Tổng chiều dài D16 = 2 980 m; trọng lượng đơn vị = 0,00617 x d^2 (kg/m)",en:"Total D16 length = 2,980 m; unit weight = 0.00617 x d^2 (kg/m)"},hint:{vi:"Bản nháp lấy nhầm trọng lượng đơn vị của một đường kính khác; tính lại từ d = 16 mm.",en:"The draft used the unit weight of another diameter; recompute it from d = 16 mm."}}],sop32:{vi:"Trọng lượng đơn vị thép tròn (kg/m) = 0,00617 x d^2, d tính bằng mm; khối lượng = tổng chiều dài x trọng lượng đơn vị, làm tròn đến 1 kg. Hao hụt đã nằm trong định mức, không cộng vào khối lượng đo bóc.",en:"Unit weight of round bar (kg/m) = 0.00617 x d^2, d in mm; weight = total length x unit weight, rounded to 1 kg. Wastage is already in the norm and is not added to the measured quantity."},context:{label:"DỰ TOÁN / BOQ-2318",metrics:[{label:{vi:"Tổng chiều dài D16",en:"Total D16 length"},value:"2,980 m"},{label:{vi:"Số móng M1",en:"M1 footings"},value:"24"},{label:{vi:"Trọng lượng đơn vị",en:"Unit weight formula"},value:"0.00617 x d^2 kg/m"}]},crisis:{vi:"Chỉ huy trưởng nhà thầu nhắn: “Cứ để nhóm thép >18 mm cho đơn giá cao hơn, cộng thêm 5% hao hụt vào khối lượng nữa. Chủ đầu tư không soát kỹ đâu, dự toán cao thì dễ thương thảo.”",en:"The contractor's site manager texts: “Keep the >18 mm group for the higher rate and add 5% wastage to the quantity too. The client never checks closely, and a high estimate is easier to negotiate.”"},options:{safe:{vi:"Áp đúng nhóm định mức theo đường kính, giữ khối lượng theo bản vẽ, không cộng hao hụt trùng; báo trưởng nhóm dự toán và lưu bảng tính, bản vẽ làm căn cứ.",en:"Apply the norm group by bar diameter, keep the quantity per the drawings with no double-counted wastage; inform the lead QS and file the worksheet and drawings as evidence."},shortcut:{vi:"Giữ nhóm >18 mm và cộng 5% hao hụt như đề nghị để dự toán có dư địa thương thảo.",en:"Keep the >18 mm group and add 5% wastage as asked to leave room for negotiation."},wait:{vi:"Chuyển nguyên bản nháp cho chủ đầu tư và để họ tự phát hiện sai sót.",en:"Send the draft to the client unchanged and let them find the errors."}},questions:{vi:["Giải thích vì sao thép D16 thuộc nhóm D10-18 và cách bạn tính lại khối lượng từ tổng chiều dài.","Đề nghị cộng hao hụt và nâng nhóm định mức gây rủi ro gì cho dự án và cho bạn? Bạn xử lý ra sao?"],en:["Explain why D16 belongs to the D10-18 group and how you recomputed the weight from the total length.","What risks do the proposals to add wastage and upgrade the norm group create for the project and for you? How do you respond?"]},hints:{vi:["Đặt bản nháp cạnh bảng thống kê cốt thép và đánh dấu dòng nhóm định mức không khớp đường kính thanh.","Theo SOP mục 3.2, tính trọng lượng đơn vị từ đường kính thực của thanh rồi mới nhân với tổng chiều dài.","Đọc SOP mục 4.2: đo bóc theo thiết kế, không thổi phồng khối lượng; mọi áp lực phải báo trưởng nhóm."],en:["Place the draft next to the bar schedule and flag the norm group line that does not match the bar diameter.","Under SOP 3.2, compute the unit weight from the actual bar diameter before multiplying by the total length.","Re-read SOP 4.2: measure per the design and never inflate quantities; escalate any pressure to the lead QS."]}},learning:{summary:{vi:"Kỹ sư dự toán và quản lý chi phí xây dựng (QS) đo bóc khối lượng từ hồ sơ thiết kế, áp định mức và đơn giá, lập tổng mức đầu tư, dự toán, giá gói thầu và kiểm soát chi phí suốt vòng đời dự án. Họ giúp chủ đầu tư và nhà thầu ra quyết định dựa trên số liệu chính xác, minh bạch. Nghề đòi hỏi đọc bản vẽ thành thạo, nắm vững quy định quản lý chi phí đầu tư xây dựng và giữ chuẩn mực trung thực khi lập giá trị.",en:"A quantity surveyor (QS) measures quantities from design documents, applies norms and rates, prepares the investment budget, estimates and package prices, and controls cost across the project life cycle. They help clients and contractors decide on accurate, transparent figures. The role requires fluent drawing reading, solid knowledge of construction cost regulations and strict honesty when valuing work."},responsibilities:{vi:["Đo bóc khối lượng từ bản vẽ thiết kế và chỉ dẫn kỹ thuật theo quy tắc đo bóc thống nhất.","Áp định mức, đơn giá và chỉ số giá phù hợp để lập dự toán, giá gói thầu.","Lập và kiểm soát tổng mức đầu tư, dự toán; theo dõi chênh lệch giữa dự toán và thực tế.","Thẩm tra hồ sơ thanh toán, khối lượng phát sinh và điều chỉnh giá hợp đồng.","Lập báo cáo chi phí định kỳ, quyết toán và lưu trữ hồ sơ làm căn cứ kiểm toán."],en:["Measure quantities from design drawings and specifications under consistent measurement rules.","Apply suitable norms, rates and price indices to prepare estimates and package prices.","Prepare and control the investment budget and estimates, tracking variance against actuals.","Verify payment applications, additional quantities and contract price adjustments.","Issue periodic cost reports and final accounts and archive records for audit."]},competencies:[{name:{vi:"Đo bóc khối lượng",en:"Quantity take-off"},desc:{vi:"Đọc bản vẽ kiến trúc, kết cấu, MEP; đo bóc đúng đơn vị, quy cách, không trùng, không sót.",en:"Read architectural, structural and MEP drawings; measure in the right units and specs with no double counting or omissions."}},{name:{vi:"Định mức & đơn giá",en:"Norms & rates"},desc:{vi:"Chọn đúng mã hiệu định mức theo điều kiện thi công, quy cách vật liệu và biện pháp.",en:"Select the right norm code for site conditions, material specification and method."}},{name:{vi:"Kiểm soát chi phí",en:"Cost control"},desc:{vi:"Theo dõi dòng tiền, cảnh báo vượt chi và đề xuất giải pháp tối ưu chi phí.",en:"Track cash flow, warn of overruns and propose value engineering options."}},{name:{vi:"Công cụ số",en:"Digital tools"},desc:{vi:"Dùng phần mềm dự toán, bảng tính và bóc tách từ mô hình BIM để giảm sai sót.",en:"Use estimating software, spreadsheets and BIM-based take-off to reduce errors."}},{name:{vi:"Trung thực nghề nghiệp",en:"Professional honesty"},desc:{vi:"Không thổi phồng khối lượng, không áp sai định mức để có lợi cho bất kỳ bên nào.",en:"Never inflate quantities or misapply norms to favour any party."}}],knowledge:{vi:["Nghị định 10/2021/NĐ-CP về quản lý chi phí đầu tư xây dựng.","Thông tư 11/2021/TT-BXD hướng dẫn xác định và quản lý chi phí đầu tư xây dựng.","Thông tư 12/2021/TT-BXD ban hành định mức xây dựng và các văn bản sửa đổi, bổ sung.","Thông tư 13/2021/TT-BXD hướng dẫn xác định chỉ tiêu kinh tế kỹ thuật và đo bóc khối lượng công trình.","Cơ cấu chi phí xây dựng: chi phí trực tiếp, chi phí gián tiếp, thu nhập chịu thuế tính trước và thuế giá trị gia tăng.","Công thức trọng lượng thép tròn 0,00617 x d^2 (kg/m) và đơn vị đo bóc của từng loại công tác."],en:["Decree 10/2021/ND-CP on construction investment cost management.","Circular 11/2021/TT-BXD guiding the determination and management of construction investment cost.","Circular 12/2021/TT-BXD issuing construction norms, with its amendments and supplements.","Circular 13/2021/TT-BXD guiding techno-economic indicators and quantity measurement of works.","Construction cost structure: direct cost, indirect cost, pre-calculated taxable income and value added tax.","Round bar weight formula 0.00617 x d^2 (kg/m) and the measurement unit of each work type."]},tools:["Phần mềm lập dự toán xây dựng","Microsoft Excel","Phần mềm đọc bản vẽ CAD","Phần mềm bóc tách khối lượng từ BIM","Cơ sở dữ liệu giá vật liệu địa phương"],kpis:{vi:["Sai lệch khối lượng giữa dự toán và quyết toán (mục tiêu dưới 3%).","Tỷ lệ hồ sơ dự toán qua thẩm tra không phải sửa lớn.","Thời gian hoàn thành bộ dự toán so với kế hoạch.","Số khoản phát sinh bị từ chối do thiếu căn cứ."],en:["Quantity variance between estimate and final account (target below 3%).","Share of estimates passing independent review without major changes.","Estimate completion time against plan.","Number of variation items rejected for lack of evidence."]},day:[{time:"08:00",vi:"Nhận bản vẽ phát hành mới, kiểm tra danh mục phiên bản và phạm vi thay đổi.",en:"Receive newly issued drawings and check the revision register and scope of changes."},{time:"09:30",vi:"Đo bóc bê tông, cốt thép, ván khuôn phần móng theo bản vẽ hiệu lực.",en:"Take off foundation concrete, rebar and formwork from the current drawings."},{time:"13:30",vi:"Áp mã hiệu định mức, đơn giá vật liệu, nhân công, máy và lập bảng tổng hợp.",en:"Apply norm codes and material, labour and plant rates and build the summary."},{time:"15:30",vi:"Họp với kỹ sư kết cấu làm rõ chi tiết chưa đủ thông tin để đo bóc.",en:"Meet the structural engineer to clarify details lacking information for take-off."},{time:"17:00",vi:"Soát xét chéo bảng tính, ghi nhật ký giả định và lưu hồ sơ.",en:"Peer-review worksheets, log assumptions and archive the file."}],mistakes:{vi:["Lấy nhầm trọng lượng đơn vị của đường kính khác khi tính khối lượng thép.","Cộng hao hụt vào khối lượng đo bóc trong khi định mức đã bao gồm hao hụt.","Đo bóc từ bản vẽ đã hết hiệu lực, không đối chiếu danh mục phiên bản."],en:["Using the unit weight of another diameter when computing rebar weight.","Adding wastage to measured quantities when the norm already includes it.","Measuring from superseded drawings without checking the revision register."]},career:[{vi:"Kỹ thuật viên đo bóc khối lượng",en:"Quantity take-off technician"},{vi:"Kỹ sư dự toán (QS)",en:"Quantity surveyor (QS)"},{vi:"Kỹ sư QS chính, kiểm soát chi phí",en:"Senior QS and cost controller"},{vi:"Giám đốc quản lý chi phí dự án",en:"Project cost management director"}],glossary:[{term:"BOQ",vi:"Bảng khối lượng mời thầu hoặc dự toán, liệt kê công việc, đơn vị, khối lượng và đơn giá.",en:"Bill of quantities listing work items, units, quantities and rates for tender or estimate."},{term:"Định mức dự toán",vi:"Mức hao phí vật liệu, nhân công, máy thi công để hoàn thành một đơn vị khối lượng công tác.",en:"Standard consumption of materials, labour and plant to complete one unit of construction work."},{term:"Take-off",vi:"Quá trình đo bóc khối lượng từ bản vẽ, mô hình theo quy tắc đo thống nhất.",en:"Process of measuring quantities from drawings or models under agreed measurement rules."},{term:"Chi phí gián tiếp",vi:"Gồm chi phí chung, nhà tạm để ở và điều hành thi công, công việc không xác định được khối lượng từ thiết kế và chi phí gián tiếp khác.",en:"Covers overheads, temporary site housing and offices, items not quantifiable from the design and other indirect costs."},{term:"Cost plan",vi:"Kế hoạch chi phí phân bổ ngân sách theo hạng mục, làm chuẩn kiểm soát chi phí khi thiết kế và thi công.",en:"Budget allocated by element, used as the baseline to control cost during design and construction."}],quiz:[{q:{vi:"Trọng lượng đơn vị của thép D20 theo công thức 0,00617 x d^2 là bao nhiêu?",en:"What is the unit weight of a D20 bar using 0.00617 x d^2?"},options:{vi:["1,58 kg/m","2,00 kg/m","2,47 kg/m","3,85 kg/m"],en:["1.58 kg/m","2.00 kg/m","2.47 kg/m","3.85 kg/m"]},answer:2,explain:{vi:"0,00617 x 20^2 = 0,00617 x 400 = 2,468, làm tròn 2,47 kg/m.",en:"0.00617 x 20^2 = 0.00617 x 400 = 2.468, rounded to 2.47 kg/m."}},{q:{vi:"Theo cơ cấu chi phí xây dựng hiện hành, chi phí nhà tạm để ở và điều hành thi công thuộc nhóm nào?",en:"Under the current construction cost structure, which group covers temporary site housing and offices?"},options:{vi:["Chi phí trực tiếp","Chi phí gián tiếp","Chi phí dự phòng","Chi phí quản lý dự án"],en:["Direct cost","Indirect cost","Contingency","Project management cost"]},answer:1,explain:{vi:"Chi phí gián tiếp gồm chi phí chung, nhà tạm để ở và điều hành thi công và một số khoản không xác định được khối lượng từ thiết kế.",en:"Indirect cost includes overheads, temporary site housing and offices and some items not quantifiable from the design."}},{q:{vi:"Nhà thầu đề nghị bạn cộng thêm 5% khối lượng “cho dư” trước khi trình chủ đầu tư. Bạn làm gì?",en:"The contractor asks you to add 5% to the quantities “for safety” before submitting to the client. What do you do?"},options:{vi:["Đồng ý vì đó là thông lệ","Cộng 2% cho vừa phải","Gửi bản nháp mà không ý kiến","Từ chối, giữ khối lượng theo thiết kế, báo trưởng nhóm và lưu căn cứ"],en:["Agree because it is common practice","Add 2% as a compromise","Send the draft without comment","Refuse, keep design quantities, inform the lead and keep evidence"]},answer:3,explain:{vi:"Khối lượng đo bóc phải theo thiết kế; thổi phồng là sai lệch có chủ đích và có thể bị xử lý khi thẩm tra, kiểm toán.",en:"Measured quantities must follow the design; inflating them is deliberate misstatement and can be sanctioned in review or audit."}},{q:{vi:"Thép D12 khi áp định mức sản xuất, lắp dựng cốt thép thuộc nhóm nào?",en:"Which norm group applies to D12 bars for rebar fabrication and fixing?"},options:{vi:["Nhóm đường kính <=18 mm","Nhóm đường kính <=10 mm","Nhóm đường kính >18 mm","Không phân nhóm"],en:["Diameter group <=18 mm","Diameter group <=10 mm","Diameter group >18 mm","No grouping"]},answer:0,explain:{vi:"Đường kính 12 mm lớn hơn 10 mm và không quá 18 mm nên thuộc nhóm <=18 mm.",en:"A 12 mm bar is above 10 mm and not over 18 mm, so it falls in the <=18 mm group."}}],tools_en:["Construction cost estimating software","Microsoft Excel","CAD drawing viewer","BIM quantity takeoff software","Local material price database"]}}})})(window.KKR);
